import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const rootDir = path.resolve(__dirname, '..');
const srcPath = path.join(
  rootDir,
  'node_modules',
  '@jitsi',
  'rnnoise-wasm',
  'dist',
  'rnnoise-sync.js'
);
const outPath = path.join(rootDir, 'src', 'utils', 'rnnoiseSyncInline.js');

if (!fs.existsSync(srcPath)) {
  throw new Error(
    `RNNoise WASM sync bundle not found at ${srcPath}. Run npm install first.`
  );
}

const raw = fs.readFileSync(srcPath, 'utf8');

// 1. Replace ES-module `import.meta.url` so the script executes cleanly in classic <script> & file:// WebViews.
// 2. Replace `export default createRNNWasmModuleSync;` with global registration `__createOpungRnnoiseSync`.
let patched = raw
  .replace(/var\s+_scriptDir\s*=\s*import\.meta\.url\s*;/, 'var _scriptDir = undefined;')
  .replace(
    /export\s+default\s+createRNNWasmModuleSync\s*;?\s*$/,
    '(typeof globalThis !== "undefined" ? globalThis : window).__createOpungRnnoiseSync = createRNNWasmModuleSync;'
  );

if (/import\.meta/.test(patched)) {
  throw new Error('Found leftover import.meta reference in patched RNNoise script');
}
if (/export\s+default/.test(patched)) {
  throw new Error('Found leftover export default in patched RNNoise script');
}
if (/<\/script/i.test(patched)) {
  throw new Error('Found unsafe </script sequence in patched RNNoise script');
}

const jsOutput =
  '// AUTO-GENERATED by scripts/generate-rnnoise-bundle.mjs from @jitsi/rnnoise-wasm (RNNoise 0.2 Sync WASM).\n' +
  '// Do not edit manually.\n' +
  'export const RNNOISE_SYNC_INLINE_SCRIPT = ' +
  JSON.stringify(patched) +
  ';\n';

fs.writeFileSync(outPath, jsOutput, 'utf8');
console.log(
  `Generated src/utils/rnnoiseSyncInline.js (${(Buffer.byteLength(jsOutput) / 1024).toFixed(1)} KB)`
);
